import {disasterReliefReport} from './disaster-relief.js?v=earthquake-magnitude-1';
import {businessIncomeReport} from './business.js?v=earthquake-magnitude-1';
import {annualAccounts,setAutoBudget,budgetForecast,SECTORS} from './economy.js?v=earthquake-magnitude-1';
import {applyBudget,borrow} from './engine.js?v=earthquake-magnitude-1';
const names={residential:'Residential',commercial:'Commercial',industrial:'Industrial'};
export function showFinance(ui){
 const {city,dialog,close,update,save,clearUndo,notify,review}=ui,c=city(),fmt=n=>'§'+Math.round(n).toLocaleString(),$=s=>document.querySelector(s),f=c.finance;
 const loanDate=m=>new Date(Date.UTC((c.startYear||1950)+Math.floor(m/12),m%12)).toLocaleDateString('en-US',{month:'short',year:'numeric',timeZone:'UTC'});
 const annual=annualAccounts(c);if(annual){f.pendingBudgetReview=null;save();}
 dialog(annual?`Year-end budget · ${annual.year}`:'Budget & taxes',`${annual?`<p>${annual.funds<0?'The treasury is negative. Review taxes, spending or a loan before continuing.':'Review the completed year and set your budget for the next one.'}</p><div class="metric-grid"><div><small>Revenue · ${annual.months} recorded months</small><strong>${fmt(annual.income)}</strong></div><div><small>Operating / regional expenses</small><strong>${fmt(annual.expenses)}</strong></div><div><small>Loan repayments</small><strong>${fmt(annual.loanPayments)}</strong></div><div><small>Contract penalties</small><strong>${fmt(annual.penalties)}</strong></div><div><small>One-time recovery grants</small><strong>${fmt(annual.disasterRelief)}</strong></div><div><small>Year-end treasury</small><strong>${fmt(annual.funds)}</strong></div></div>`:''}<div class="finance-tabs"><button id="financeAccounts" class="active">Budget</button><button id="financeBusiness">Business deals</button><button id="financeOrdinances">Ordinances</button><button id="financeHistory">History</button><button id="financeReview">Milestone feedback</button></div><div id="accountsPane">${disasterReliefReport(c)}<p>Set taxes for each sector and fund road maintenance. Changes affect demand, revenue, and the condition of your city.</p><label class="ordinance"><input id="autoBudget" type="checkbox" ${f.autoBudget?'checked':''}><span>Auto Budget · keep current settings and skip annual review while funds are nonnegative</span></label><p class="fine">With Auto Budget off, play pauses for a review after each completed year. Auto Budget never changes taxes or funding for you. Negative year-end funds always trigger a review. Close this window and press Play when ready.</p><h3>Finance milestone checklist</h3><ul><li>${f.taxesChanged?'✓ ':''}Set sector taxes and compare demand.</li><li>${f.roadCondition>=90?'✓ ':''}Keep roads at 90% condition or better.</li><li>${f.monthsInSurplus>=12?'✓ ':''}Maintain a positive operating balance for twelve months (${Math.min(12,f.monthsInSurplus)} / 12).</li><li>${budgetForecast(c).projectedYearEnd>=0?'✓ ':''}Keep projected year-end funds positive after loan commitments.</li></ul><h3>Tax rates</h3><div class="tax-inputs">${SECTORS.map(s=>`<label>${names[s]} (%)<input id="tax-${s}" type="number" min="0" max="20" step="0.1" value="${f.taxes[s]}"></label>`).join('')}</div><label>Road maintenance: <strong id="fundingValue">${f.roadFunding}%</strong><input id="roadFunding" type="range" min="0" max="150" step="5" value="${f.roadFunding}"></label><p class="fine">100% maintains and repairs roads. Underfunding gradually creates potholes and can interrupt access. Funding above 100% costs more without improving fully maintained roads.</p><div id="budgetPreview"></div><div class="actions"><button id="applyBudget" class="primary">Apply budget</button></div><h3>Loans · ${f.loans.length} / 10 outstanding</h3><p>Borrow in §5,000 increments, up to §25,000 per loan. Ten annual payments total 150% of principal. Loans cannot be repaid early.</p><label>Principal<select id="loanAmount">${[5000,10000,15000,20000,25000].map(v=>`<option value="${v}">${fmt(v)}</option>`).join('')}</select></label><p id="loanTerms"></p><button id="takeLoan" ${f.loans.length>=10?'disabled':''}>Take loan</button><div class="table-scroll"><table><thead><tr><th scope="col">Loan</th><th scope="col">Annual payment</th><th scope="col">Next due</th><th scope="col">Payments left</th></tr></thead><tbody>${f.loans.map(l=>`<tr><td>${fmt(l.principal)}</td><td>${fmt(l.principal*.15)}</td><td>${loanDate(l.issuedMonth+(l.paymentsMade+1)*12)}</td><td>${10-l.paymentsMade}</td></tr>`).join('')||'<tr><td colspan="4">No outstanding loans.</td></tr>'}</tbody></table></div><p class="fine">Manage police, fire, healthcare, and education funding through Civic services in the city toolkit. Manage transit funding in Transport & commuting. Revenue constants and environmental effects remain approximations.</p></div><div id="historyPane" hidden><label>History metric<select id="historyMetric"><option value="funds">Treasury</option><option value="population">Population</option><option value="income">Monthly revenue</option><option value="expenses">Operating expenses</option><option value="landValue">Average land value</option><option value="pollution">Average air pollution</option><option value="crime">Crime</option><option value="education">Education</option><option value="lifeExpectancy">Life expectancy</option></select></label><div id="historyChart"></div></div>`);
 function draft(){return{taxes:Object.fromEntries(SECTORS.map(s=>[s,Number($(`#tax-${s}`).value)])),funding:Number($('#roadFunding').value)};}
 function renderPreview(){const d=draft();if(SECTORS.some(s=>d.taxes[s]<0||d.taxes[s]>20||!Number.isFinite(d.taxes[s]))) {$('#budgetPreview').textContent='Enter tax rates between 0% and 20%.';return;}
 const b=budgetForecast(c,d.taxes,d.funding);$('#fundingValue').textContent=d.funding+'%';$('#budgetPreview').innerHTML=`<h3>Monthly operating budget</h3><div class="table-scroll"><table><thead><tr><th scope="col">Income</th><th scope="col">Per month</th></tr></thead><tbody>${SECTORS.map(s=>`<tr><td>${names[s]} taxes</td><td>${fmt(b.revenues[s])}</td></tr>`).join('')}<tr><td>Business deals</td><td>${fmt(c.stats.businessIncome||0)}</td></tr><tr><td>Neighbor deals</td><td>${fmt(c.stats.regionIncome)}</td></tr><tr><td>Ordinance revenue · parking fines</td><td>${fmt(b.ordinanceIncome)}</td></tr><tr><td>Transit fares</td><td>${fmt(c.stats.transitFare)}</td></tr></tbody></table><table><thead><tr><th scope="col">Expenses</th><th scope="col">Per month</th></tr></thead><tbody>${Object.entries(b.spending).map(([name,value])=>`<tr><td>${name[0].toUpperCase()+name.slice(1)}</td><td>${fmt(value)}</td></tr>`).join('')}</tbody></table></div>${businessIncomeReport(c)}<div class="metric-grid"><div><small>Monthly operating balance</small><strong>${b.balance>=0?'+':''}${fmt(b.balance)}</strong></div><div><small>Projected year-end funds</small><strong>${fmt(b.projectedYearEnd)}</strong></div><div><small>Loan payments before year-end</small><strong>${fmt(b.yearDebtDue)}</strong></div><div><small>Road condition</small><strong>${Math.round(f.roadCondition)}%</strong></div></div><p class="fine">Projection covers ${b.monthsLeft} months at the current population and land values, subtracting scheduled loan payments. Construction and future growth are not included. The preview uses the entered rates; Apply budget saves them.</p>`;
 }
 function renderTerms(){const amount=Number($('#loanAmount').value);$('#loanTerms').textContent=`Receive ${fmt(amount)} now. Pay ${fmt(amount*.15)} each year for ten years (${fmt(amount*1.5)} total). First payment: ${loanDate(c.month+12)}.`;}
 function renderHistory(){const metric=$('#historyMetric').value,rows=c.history.filter(h=>Number.isFinite(h[metric]));if(!rows.length){$('#historyChart').innerHTML='<p>No history for this metric yet. Run the city for a few months.</p>';return;}
 const values=rows.map(h=>h[metric]),min=Math.min(...values),max=Math.max(...values),range=max-min||1,points=rows.map((h,i)=>`${35+i/Math.max(1,rows.length-1)*480},${155-(h[metric]-min)/range*125}`).join(' '),label=$('#historyMetric').selectedOptions[0].textContent;
 $('#historyChart').innerHTML=`<svg viewBox="0 0 550 195" role="img" aria-label="${label} over ${rows.length} months"><path d="M35 20V160H520" fill="none" stroke="#769ba2"/><polyline points="${points}" fill="none" stroke="#c4ed89" stroke-width="3"/><text x="35" y="185" fill="#b0c9ce" font-size="12">${loanDate(rows[0].month)}</text><text x="520" y="185" text-anchor="end" fill="#b0c9ce" font-size="12">${loanDate(rows.at(-1).month)}</text></svg><p>Range: ${Math.round(min).toLocaleString()}–${Math.round(max).toLocaleString()}. Latest: ${Math.round(values.at(-1)).toLocaleString()}.</p><div class="table-scroll"><table><caption>Most recent twelve months</caption><thead><tr><th scope="col">Month</th><th scope="col">${label}</th></tr></thead><tbody>${rows.slice(-12).reverse().map(h=>`<tr><td>${loanDate(h.month)}</td><td>${Math.round(h[metric]).toLocaleString()}</td></tr>`).join('')}</tbody></table></div>`;
 }
 for(const sector of SECTORS)$(`#tax-${sector}`).oninput=renderPreview;$('#roadFunding').oninput=renderPreview;$('#loanAmount').onchange=renderTerms;$('#historyMetric').onchange=renderHistory;
 $('#applyBudget').onclick=()=>{const d=draft(),result=applyBudget(c,d.taxes,d.funding);if(!result.ok)return notify(result.error);clearUndo();update();save();notify('Budget applied. Tax rates and road funding updated.');showFinance(ui);};
 $('#takeLoan').onclick=()=>{const result=borrow(c,Number($('#loanAmount').value));if(!result.ok)return notify(result.error);clearUndo();update();save();notify(`Loan received: ${fmt(result.loan.principal)}.`);showFinance(ui);};
 $('#financeBusiness').onclick=()=>ui.business();
 $('#financeOrdinances').onclick=()=>ui.ordinances();
 $('#financeHistory').onclick=()=>{$('#accountsPane').hidden=true;$('#historyPane').hidden=false;$('#financeHistory').classList.add('active');$('#financeAccounts').classList.remove('active');renderHistory();};
 $('#financeAccounts').onclick=()=>{$('#accountsPane').hidden=false;$('#historyPane').hidden=true;$('#financeHistory').classList.remove('active');$('#financeAccounts').classList.add('active');};$('#financeReview').onclick=()=>review(3);
 $('#autoBudget').onchange=()=>{const r=setAutoBudget(c,$('#autoBudget').checked);if(!r.ok)return notify(r.error);clearUndo();save();notify(f.autoBudget?'Auto Budget enabled. Current settings will be kept.':'Annual budget reviews enabled.');};
 renderPreview();renderTerms();
}
